extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket_scene := await instantiate_scene("res://basket.tscn")
	if not check("basket_scene", basket_scene != null, "La scena basket.tscn deve caricarsi correttamente"):
		return

	var stars_array = get_prop(basket_scene, "stars")
	if not check("stars_prop", typeof(stars_array) == TYPE_ARRAY, "basket.gd deve avere la proprieta' stars di tipo Array"):
		return

	check("stars_count", stars_array.size() == 5, "All'inizio devono esserci 5 stelle nell'Array stars")

	var star1 = stars_array[0] if stars_array.size() > 0 else null
	var initial_y: float = star1.position.y if star1 != null else 0.0
	await wait_seconds(0.4)

	if star1 != null:
		check("star_moving", star1.position.y > initial_y, "Le stelle nell'Array devono muoversi verso il basso")

	if stars_array.size() > 0:
		var target_star = stars_array[0]
		basket_scene.position = target_star.position
		await wait_frames(3)
		check("star_respawned", stars_array.size() == 5, "Dopo aver raccolto una stella, l'Array stars deve mantenere 5 elementi")
		check("star_removed_from_scene", target_star.get_parent() == null, "La stella raccolta deve essere rimossa dalla scena")

