extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket_scene := await instantiate_scene("res://basket.tscn")
	if not check("basket_scene", basket_scene != null, "La scena basket.tscn deve caricarsi senza errori"):
		return

	var stars_array = get_prop(basket_scene, "stars")
	if not check("stars_array", typeof(stars_array) == TYPE_ARRAY and stars_array.size() > 0, "L'array stars deve contenere le stelle"):
		return

	var star1 = stars_array[0]
	var initial_speed: float = get_prop(star1, "fall_speed", 0.0)

	if not check("has_boost", has_function(basket_scene, "boost_all_stars"), "basket.gd deve contenere la funzione boost_all_stars"):
		return

	basket_scene.call("boost_all_stars", 20.0)
	var new_speed: float = get_prop(star1, "fall_speed", 0.0)
	check("boost_works", new_speed == initial_speed + 20.0, "boost_all_stars(20.0) deve aumentare fall_speed della stella di 20.0")

	var speed_before_score: float = get_prop(star1, "fall_speed", 0.0)
	if has_function(basket_scene, "add_score"):
		basket_scene.call("add_score", 10)
		var speed_after_score: float = get_prop(star1, "fall_speed", 0.0)
		check("add_score_boosts", speed_after_score == speed_before_score + 10.0, "add_score deve chiamare boost_all_stars(10.0) e aumentare la velocita' delle stelle")

