var coins: Array[Sprite2D] = []


func _ready() -> void:
	# Crea 3 monete che cadono oltre la soglia dei 500 pixel
	for i in range(3):
		spawn_coin(Vector2(100.0 + i * 100.0, 490.0))


func _process(delta: float) -> void:
	clean_coins()


func spawn_coin(pos: Vector2) -> void:
	var coin_scene: PackedScene = load("res://coin.tscn")
	var new_coin: Sprite2D = coin_scene.instantiate() as Sprite2D
	new_coin.position = pos
	add_child(new_coin)
	coins.append(new_coin)


func clean_coins() -> void:
	# ERRORE: Scorre l'array in avanti durante l'eliminazione!
	for i in range(coins.size()):
		if coins[i].position.y > 500.0:
			remove_child(coins[i])
			coins.remove_at(i)

